Here is the commit message:
octeon_ep: Fix memory leak in octep_device_setup()

In octep_device_setup(), if octep_ctrl_net_init() fails, the function
returns directly without unmapping the mapped resources and freeing the
allocated configuration memory.

Fix this by jumping to the unsupported_dev label, which performs the
necessary cleanup. This aligns with the error handling logic of other
paths in this function.

Compile tested only. Issue found using a prototype static analysis tool
and code review.

Fixes: 577f0d1b1c5f ("octeon_ep: add separate mailbox command and response queues")
Signed-off-by: Zilin Guan <zilin@seu.edu.cn>
Reviewed-by: Vadim Fedorenko <vadim.fedorenko@linux.dev>
Link: https://patch.msgid.link/20260121130551.3717090-1-zilin@seu.edu.cn
Signed-off-by: Jakub Kicinski <kuba@kernel.org>

Here is the root cause:
In octep_device_setup(), a failure of octep_ctrl_net_init() leads to a direct return without invoking the cleanup code under the unsupported_dev label, resulting in a memory leak of previously allocated resources.

Here is the patch:
  */
 int octep_device_setup(struct octep_device *oct)
 {
 	struct pci_dev *pdev = oct->pdev;
 	int i, ret;

 	/* allocate memory for oct->conf */
 	oct->conf = kzalloc(sizeof(*oct->conf), GFP_KERNEL);
 	if (!oct->conf)
 		return -ENOMEM;

 	/* Map BAR regions */
 	for (i = 0; i < OCTEP_MMIO_REGIONS; i++) {
 		oct->mmio[i].hw_addr =
 			ioremap(pci_resource_start(oct->pdev, i * 2),
 				pci_resource_len(oct->pdev, i * 2));
 		if (!oct->mmio[i].hw_addr)
 			goto unmap_prev;

 		oct->mmio[i].mapped = 1;
 	}

 	oct->chip_id = pdev->device;
 	oct->rev_id = pdev->revision;
 	dev_info(&pdev->dev, "chip_id = 0x%x\n", pdev->device);

 	switch (oct->chip_id) {
 	case OCTEP_PCI_DEVICE_ID_CN98_PF:
 	case OCTEP_PCI_DEVICE_ID_CN93_PF:
 	case OCTEP_PCI_DEVICE_ID_CNF95N_PF:
 		dev_info(&pdev->dev, "Setting up OCTEON %s PF PASS%d.%d\n",
 			 octep_devid_to_str(oct), OCTEP_MAJOR_REV(oct),
 			 OCTEP_MINOR_REV(oct));
 		octep_device_setup_cn93_pf(oct);
 		break;
 	case OCTEP_PCI_DEVICE_ID_CNF10KA_PF:
 	case OCTEP_PCI_DEVICE_ID_CN10KA_PF:
 	case OCTEP_PCI_DEVICE_ID_CNF10KB_PF:
 	case OCTEP_PCI_DEVICE_ID_CN10KB_PF:
 		dev_info(&pdev->dev, "Setting up OCTEON %s PF PASS%d.%d\n",
 			 octep_devid_to_str(oct), OCTEP_MAJOR_REV(oct), OCTEP_MINOR_REV(oct));
 		octep_device_setup_cnxk_pf(oct);
 		break;
 	default:
 		dev_err(&pdev->dev,
 			"%s: unsupported device\n", __func__);
 		goto unsupported_dev;
 	}


 	ret = octep_ctrl_net_init(oct);
 	if (ret)
-		return ret;
+		goto unsupported_dev;

 	INIT_WORK(&oct->tx_timeout_task, octep_tx_timeout_task);
 	INIT_WORK(&oct->ctrl_mbox_task, octep_ctrl_mbox_task);
 	INIT_DELAYED_WORK(&oct->intr_poll_task, octep_intr_poll_task);
 	oct->poll_non_ioq_intr = true;
 	queue_delayed_work(octep_wq, &oct->intr_poll_task,
 			   msecs_to_jiffies(OCTEP_INTR_POLL_TIME_MSECS));

 	atomic_set(&oct->hb_miss_cnt, 0);
 	INIT_DELAYED_WORK(&oct->hb_task, octep_hb_timeout_task);

 	return 0;

 unsupported_dev:
 	i = OCTEP_MMIO_REGIONS;
 unmap_prev:
 	while (i--)
 		iounmap(oct->mmio[i].hw_addr);

 	kfree(oct->conf);
 	return -1;
 }



